<?php

/**
 * Hand-written code. NOT generated by Speakeasy. Safe from regeneration.
 *
 * @see docs/REGENERATION.md
 */

declare(strict_types=1);

namespace Factuarea\Sdk\Tests\Contract;

use Factuarea\Sdk\Factuarea;
use PHPUnit\Framework\TestCase;
use ReflectionClass;
use ReflectionMethod;
use ReflectionNamedType;
use ReflectionProperty;

/**
 * The published method surface of the SDK and the pinned contract are the SAME set.
 *
 * After a regeneration the only trustworthy proof that nothing was lost or
 * invented is a two-way diff: every operation the pinned `spec/openapi.json`
 * declares must have a callable method, and every callable method must answer to
 * a declared operation. A one-way check passes happily while the generator
 * silently drops a whole family.
 *
 * The comparison is by METHOD NAME, not by accessor path, on purpose: the
 * generation overlays of `.speakeasy/overlays/` may re-group an operation (see
 * `product-options-namespace.yaml`, which moves `products.options` out of the
 * way of the PHP runtime `Utils\Options` class) without touching the pinned
 * contract, so the accessor path legitimately differs from the group the
 * contract declares. The method name is derived from `operationId`, which no
 * overlay rewrites, so it is stable across the whole chain.
 *
 * Method names are derived the way the Speakeasy PHP generator derives them:
 * `public-api.v1.sales_orders.confirm` becomes `publicApiV1SalesOrdersConfirm`.
 */
final class PublicMethodSurfaceTest extends TestCase
{
    private const SPEC = __DIR__.'/../../spec/openapi.json';

    /** The OpenAPI fixed fields of a path item that are operations. */
    private const HTTP_METHODS = ['get', 'put', 'post', 'delete', 'options', 'head', 'patch', 'trace'];

    /**
     * Public methods the generator puts on EVERY resource class that are plumbing,
     * not operations. `getUrl` resolves the templated server URL for a call.
     *
     * Deliberately an exact allowlist: a new generated helper makes this test red
     * so a human classifies it instead of it being absorbed as an operation.
     */
    private const NON_OPERATION_METHODS = ['getUrl'];

    /**
     * Sub-namespaces of the SDK that are not part of the operation surface:
     * request/response models, the serializer and URL helpers, and the hook
     * registry. The walk stops at them.
     */
    private const NON_SURFACE_NAMESPACES = [
        'Factuarea\\Sdk\\Models\\',
        'Factuarea\\Sdk\\Utils\\',
        'Factuarea\\Sdk\\Hooks\\',
        'Factuarea\\Sdk\\Custom\\',
    ];

    /** Runtime configuration reachable from every resource class; not an operation holder. */
    private const NON_SURFACE_CLASSES = [\Factuarea\Sdk\SDKConfiguration::class];

    public function test_every_declared_operation_has_a_published_method_and_the_reverse(): void
    {
        $declared = self::declaredOperationMethods();
        $published = self::publishedOperationMethods();

        $missing = array_values(array_diff(array_keys($declared), array_keys($published)));
        $surplus = array_values(array_diff(array_keys($published), array_keys($declared)));
        sort($missing);
        sort($surplus);

        $this->assertSame(
            [],
            $missing,
            sprintf(
                'The pinned contract declares %d operations and the SDK publishes %d methods; '
                .'%d declared operations have NO method. First offenders: %s',
                count($declared),
                count($published),
                count($missing),
                self::sample($missing, $declared),
            ),
        );

        $this->assertSame(
            [],
            $surplus,
            sprintf(
                'The SDK publishes %d methods the pinned contract does not declare. First offenders: %s',
                count($surplus),
                self::sample($surplus, $published),
            ),
        );
    }

    public function test_the_pinned_contract_is_not_empty(): void
    {
        // A misplaced or truncated spec would make the diff above vacuously green.
        $this->assertGreaterThan(400, count(self::declaredOperationMethods()));
    }

    /**
     * Every group the contract declares has a class that publishes its operations,
     * so a family cannot vanish while the method count still adds up.
     *
     * @return void
     */
    public function test_every_declared_group_has_a_class_that_publishes_its_operations(): void
    {
        $published = self::publishedOperationMethods();

        $orphanGroups = [];
        foreach (self::declaredOperationsByGroup() as $group => $methodNames) {
            $holders = [];
            foreach ($methodNames as $methodName) {
                foreach ($published[$methodName] ?? [] as $class) {
                    $holders[$class] = true;
                }
            }

            if ($holders === []) {
                $orphanGroups[] = $group;
            }
        }

        sort($orphanGroups);

        $this->assertSame(
            [],
            $orphanGroups,
            sprintf('%d declared groups publish no method at all: %s', count($orphanGroups), implode(', ', array_slice($orphanGroups, 0, 20))),
        );
    }

    /**
     * @param  list<string>  $names
     * @param  array<string, list<string>>  $index
     */
    private static function sample(array $names, array $index): string
    {
        $lines = [];
        foreach (array_slice($names, 0, 15) as $name) {
            $where = $index[$name] ?? [];
            $lines[] = $name.($where === [] ? '' : ' ('.implode(', ', $where).')');
        }

        return $lines === [] ? '(none)' : implode('; ', $lines);
    }

    /**
     * Method name => the operations (`METHOD /path`) that demand it.
     *
     * @return array<string, list<string>>
     */
    private static function declaredOperationMethods(): array
    {
        $declared = [];
        foreach (self::specOperations() as [$httpMethod, $path, $operation]) {
            $declared[self::methodNameFor($operation['operationId'])][] = $httpMethod.' '.$path;
        }

        return $declared;
    }

    /**
     * Speakeasy group => the method names its operations demand.
     *
     * @return array<string, list<string>>
     */
    private static function declaredOperationsByGroup(): array
    {
        $byGroup = [];
        foreach (self::specOperations() as [, , $operation]) {
            $group = $operation['x-speakeasy-group'] ?? '(root)';
            $byGroup[$group][] = self::methodNameFor($operation['operationId']);
        }

        return $byGroup;
    }

    /**
     * @return list<array{0: string, 1: string, 2: array<string, mixed>}>
     */
    private static function specOperations(): array
    {
        /** @var array<string, mixed> $spec */
        $spec = json_decode((string) file_get_contents(self::SPEC), true, 512, JSON_THROW_ON_ERROR);

        $operations = [];
        /** @var array<string, array<string, mixed>> $paths */
        $paths = $spec['paths'] ?? [];
        foreach ($paths as $path => $pathItem) {
            foreach ($pathItem as $field => $operation) {
                if (! in_array(strtolower((string) $field), self::HTTP_METHODS, true)) {
                    continue;
                }
                $operations[] = [strtoupper((string) $field), (string) $path, $operation];
            }
        }

        return $operations;
    }

    /**
     * The generator turns `public-api.v1.sales_orders.confirm` into
     * `publicApiV1SalesOrdersConfirm`: every non-alphanumeric run is a word
     * boundary, the first word stays lower-cased and the rest are upper-cased on
     * their first character only.
     */
    private static function methodNameFor(string $operationId): string
    {
        $words = array_values(array_filter(preg_split('/[^A-Za-z0-9]+/', $operationId) ?: []));
        if ($words === []) {
            return '';
        }

        $name = lcfirst(array_shift($words));
        foreach ($words as $word) {
            $name .= ucfirst($word);
        }

        return $name;
    }

    /**
     * Method name => the classes that publish it, walking the SDK object graph
     * from the root client through its public typed properties.
     *
     * @return array<string, list<string>>
     */
    private static function publishedOperationMethods(): array
    {
        $published = [];
        $visited = [];
        self::walk(Factuarea::class, $published, $visited);

        return $published;
    }

    /**
     * @param  array<string, list<string>>  $published
     * @param  array<string, true>  $visited
     */
    private static function walk(string $class, array &$published, array &$visited): void
    {
        if (isset($visited[$class]) || in_array($class, self::NON_SURFACE_CLASSES, true)) {
            return;
        }
        $visited[$class] = true;

        $reflection = new ReflectionClass($class);

        foreach ($reflection->getMethods(ReflectionMethod::IS_PUBLIC) as $method) {
            if ($method->getDeclaringClass()->getName() !== $class) {
                continue;
            }
            if ($method->isStatic() || str_starts_with($method->getName(), '__')) {
                continue;
            }
            if (in_array($method->getName(), self::NON_OPERATION_METHODS, true)) {
                continue;
            }
            $published[$method->getName()][] = $class;
        }

        foreach ($reflection->getProperties(ReflectionProperty::IS_PUBLIC) as $property) {
            $type = $property->getType();
            if (! $type instanceof ReflectionNamedType || $type->isBuiltin()) {
                continue;
            }
            $name = $type->getName();
            if (! str_starts_with($name, 'Factuarea\\Sdk\\')) {
                continue;
            }
            foreach (self::NON_SURFACE_NAMESPACES as $excluded) {
                if (str_starts_with($name, $excluded)) {
                    continue 2;
                }
            }
            self::walk($name, $published, $visited);
        }
    }
}
